+/**
+ * 管理員更新作品 NSFW 狀態（需 write-imageManagement 權限）
+ */
+export async function updateArtworkNsfwByAdmin(
+  artworkId: string,
+  isNsfw: boolean
+) {
+  const user = await currentUser();
+  if (!user?.id) {
+    throw new Error('User not found');
+  }
+
+  const hasPermission = await checkCurrentUserPermission('write-imageManagement');
+  if (!hasPermission) {
+    throw new Error('No permission to update artwork NSFW status');
+  }
+
+  return await prisma.artwork.update({
+    where: { id: artworkId },
+    data: { isNsfw }
+  });
+}
+
