+import prisma from '@/lib/prisma';
+import { currentUser } from '@/lib/auth';
+import { checkCurrentUserPermission } from '@/data/admin/permissions';
+
+/**
+ * 管理員更新條漫公開狀態
+ */
+export async function updateWebtoonVisibilityByAdmin(
+  webtoonId: string,
+  isPublic: boolean
+) {
+  const user = await currentUser();
+  if (!user?.id) {
+    throw new Error('User not found');
+  }
+
+  const hasPermission = await checkCurrentUserPermission(
+    'write-webtoonManagement'
+  );
+  if (!hasPermission) {
+    throw new Error('No permission to update webtoon visibility');
+  }
+
+  return await prisma.webtoon.update({
+    where: { id: webtoonId },
+    data: { isPublic }
+  });
+}
