+
+              <Accordion
+                type="multiple"
+                className="w-full pb-10"
+                defaultValue={['cover', 'description', 'tags']}
+              >
+                {coverUrl && (
+                  <AccordionItem value="cover">
+                    <AccordionTrigger className="text-sm font-semibold">
+                      {t('admin.webtoons.coverLabel', {
+                        defaultMessage: '封面'
+                      })}
+                    </AccordionTrigger>
+                    <AccordionContent>
+                      <div className="relative aspect-[3/4] w-full max-w-[200px] rounded-lg overflow-hidden bg-muted">
+                        <Image
+                          src={coverUrl}
+                          alt={webtoon.name}
+                          fill
+                          className={`object-cover ${
+                            webtoon.isNsfw && !showNsfw ? 'filter blur-md' : ''
+                          }`}
+                        />
+                      </div>
+                    </AccordionContent>
+                  </AccordionItem>
+                )}
+                <AccordionItem value="description">
+                  <AccordionTrigger className="text-sm font-semibold">
+                    {t('admin.webtoons.descriptionLabel', {
+                      defaultMessage: '描述'
+                    })}
+                  </AccordionTrigger>
+                  <AccordionContent>
+                    <p className="text-sm text-foreground whitespace-pre-wrap break-words">
+                      {webtoon.description?.trim() || '-'}
+                    </p>
+                  </AccordionContent>
+                </AccordionItem>
+
+                <AccordionItem value="tags">
+                  <AccordionTrigger className="text-sm font-semibold">
+                    {t('admin.webtoons.tags', { defaultMessage: '標籤' })}
+                  </AccordionTrigger>
+                  <AccordionContent>
+                    <div className="flex flex-wrap gap-2">
+                      {webtoon.tags.length > 0 ? (
+                        webtoon.tags.map(({ tag }) => (
+                          <Badge
+                            key={tag.id}
+                            variant="secondary"
+                            className="text-xs"
+                          >
+                            {tag.name}
+                          </Badge>
+                        ))
+                      ) : (
+                        <span className="text-sm text-muted-foreground">
+                          {t('common.tag.noTags')}
+                        </span>
+                      )}
+                    </div>
+                  </AccordionContent>
+                </AccordionItem>
+
+                <AccordionItem value="dimensions">
+                  <AccordionTrigger className="text-sm font-semibold">
+                    {t('admin.webtoons.dimensions', {
+                      defaultMessage: '尺寸'
+                    })}
+                  </AccordionTrigger>
+                  <AccordionContent>
+                    <ul className="text-sm space-y-0.5 text-muted-foreground">
+                      <li>
+                        {t('admin.webtoons.canvasSize', {
+                          defaultMessage: '畫布尺寸'
+                        })}
+                        ：
+                        {typeof webtoon.canvasWidth === 'number' &&
+                        typeof webtoon.canvasHeight === 'number' &&
+                        (webtoon.canvasWidth > 0 || webtoon.canvasHeight > 0)
+                          ? `${webtoon.canvasWidth} × ${webtoon.canvasHeight}`
+                          : '-'}
+                      </li>
+                      {webtoon.cover?.width != null &&
+                        webtoon.cover?.height != null && (
+                          <li>
+                            {t('admin.webtoons.coverSize', {
+                              defaultMessage: '封面尺寸'
+                            })}
+                            ：{webtoon.cover.width} × {webtoon.cover.height}
+                          </li>
+                        )}
+                    </ul>
+                  </AccordionContent>
+                </AccordionItem>
+              </Accordion>
+            </div>
+
+            {/* 左側：條漫內容圖片（滿版、連貫、高度依圖片原始比例）；md 以下在下方 */}
+            <div className="order-2 md:order-1 flex-1 min-h-0 min-w-0 flex flex-col md:overflow-hidden border-t md:border-t-0 md:border-r relative">
+              {isSlicesLoading && allSlices.length === 0 ? (
+                <div className="flex flex-1 items-center justify-center p-8">
+                  <div className="h-8 w-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
+                </div>
+              ) : allSlices.length > 0 ? (
+                <div className="relative flex-1 min-h-0 flex flex-col">
+                  <div className="flex flex-col flex-1 min-h-0 overflow-visible md:overflow-y-auto">
+                    {allSlices.map((slice) => {
+                      const sliceUrl =
+                        slice.image?.rawUrl ?? slice.image?.url ?? null;
+                      return (
+                        <div
+                          key={slice.id}
+                          className="w-full shrink-0 bg-muted"
+                        >
+                          {sliceUrl ? (
+                            // 使用 img 以滿版寬度 + 依圖片原始高度連貫顯示（無固定比例/最小高度）
+                            // eslint-disable-next-line @next/next/no-img-element
+                            <img
+                              src={sliceUrl}
+                              alt={`${webtoon.name} - ${t(
+                                'admin.webtoons.slices',
+                                {
+                                  defaultMessage: '格'
+                                }
+                              )} ${slice.order}`}
+                              loading="lazy"
+                              className={`block w-full h-auto ${
+                                webtoon.isNsfw && !showNsfw
+                                  ? 'filter blur-md'
+                                  : ''
+                              }`}
+                            />
+                          ) : (
+                            <div className="w-full min-h-[120px] flex items-center justify-center text-muted-foreground text-sm">
+                              {t('admin.webtoons.slices', {
+                                defaultMessage: '格'
+                              })}{' '}
+                              {slice.order}
+                            </div>
+                          )}
+                        </div>
+                      );
+                    })}
+                    {hasNextPage && (
+                      <div ref={loadMoreRef} className="h-4 shrink-0" />
+                    )}
+                    {isFetchingNextPage && (
+                      <div className="flex justify-center py-2 shrink-0">
+                        <div className="h-6 w-6 border-2 border-primary border-t-transparent rounded-full animate-spin" />
+                      </div>
+                    )}
+                    {!hasNextPage && allSlices.length > 0 && (
+                      <div className="py-4 text-center text-sm text-muted-foreground shrink-0">
+                        {t('admin.webtoons.reachedBottom', {
+                          defaultMessage: '已到底部'
+                        })}
+                      </div>
+                    )}
+                    <div
+                      ref={bottomSentinelRef}
+                      className="h-2 shrink-0"
+                      aria-hidden
+                    />
+                  </div>
+                  {!isAtBottom && (
+                    <div
+                      className="absolute bottom-6 left-0 right-0 hidden md:flex justify-center pointer-events-none z-10"
+                      aria-hidden
+                    >
+                      <ChevronDown className="h-8 w-8 text-muted-foreground/80 animate-bounce" />
+                    </div>
+                  )}
+                </div>
+              ) : coverUrl ? (
+                <div className="flex-1 p-4 flex items-center justify-center min-h-0">
+                  <div className="relative aspect-[3/4] max-h-[70vh] w-full max-w-md rounded-lg overflow-hidden bg-muted">
+                    <Image
+                      src={coverUrl}
+                      alt={webtoon.name}
+                      fill
+                      className={`object-contain ${
+                        webtoon.isNsfw && !showNsfw ? 'filter blur-md' : ''
+                      }`}
+                    />
+                  </div>
+                </div>
+              ) : (
+                <div className="flex flex-1 items-center justify-center text-muted-foreground text-sm p-8">
+                  {t('admin.webtoons.noWebtoonsFound', {
+                    defaultMessage: '找不到條漫'
+                  })}
+                </div>
+              )}
+            </div>
+          </div>
+        </DialogContent>
+      </Dialog>
+
+      <DeleteWebtoonDialog
+        isOpen={isDeleteDialogOpen}
+        onOpenChange={setIsDeleteDialogOpen}
+        webtoonId={webtoon.id}
+        webtoonName={webtoon.name}
+        onSuccess={handleDeleteSuccess}
+      />
+    </>
+  );
+}
