--- /dev/null
+++ b/app/[locale]/(main)/admin/webtoons/page.tsx
@@ -0,0 +1,174 @@
+'use client';
+
+import { useInfiniteQuery, useQuery } from '@tanstack/react-query';
+import { useTranslations } from 'next-intl';
+import { useInView } from 'react-intersection-observer';
+import { useEffect, useMemo, useState } from 'react';
+import { format } from 'date-fns';
+import type { DateRange } from 'react-day-picker';
+import { BarChart3 } from 'lucide-react';
+
+import { Link } from '@/i18n/routing';
+import { getAdminWebtoons } from '@/data/admin/webtoon';
+import type { AdminWebtoon } from '@/data/admin/webtoon';
+import { getUserIdByInvitationCodeIdsAction } from '@/actions/admin/invitation-code';
+import { AdminPageGuard } from '@/components/admin/permission-guard';
+import { Button } from '@/components/ui/button';
+
+import AdminPageHeader from '../_components/admin-page-header';
+import { LoadingMore } from '../images/_components/loading-more';
+
+import { FilterControls } from './_components/filter-controls';
+import { WebtoonsContent } from './_components/webtoons-content';
+
+export default function AdminWebtoonsPage() {
+  const t = useTranslations();
+  const { ref, inView } = useInView();
+  const [userIds, setUserIds] = useState<string[]>([]);
+  const [invitationCodeIds, setInvitationCodeIds] = useState<string[]>([]);
+  const [showNsfw, setShowNsfw] = useState(false);
+  const [dateRange, setDateRange] = useState<DateRange | undefined>(undefined);
+  const [searchTerm, setSearchTerm] = useState('');
+  const [tagIds, setTagIds] = useState<string[]>([]);
+  const [isPublic, setIsPublic] = useState<boolean | undefined>(undefined);
+
+  const { data: resolvedUserIdsFromCodes } = useQuery({
+    queryKey: ['admin', 'user-ids-by-invitation-codes', invitationCodeIds],
+    queryFn: () => getUserIdByInvitationCodeIdsAction(invitationCodeIds),
+    enabled: invitationCodeIds.length > 0
+  });
+
+  const effectiveUserIds = useMemo(() => {
+    const fromCodes = resolvedUserIdsFromCodes ?? [];
+    const hasFromCodes = invitationCodeIds.length > 0 && fromCodes.length > 0;
+    if (userIds.length === 0 && !hasFromCodes) return [];
+    if (userIds.length === 0) return fromCodes;
+    if (!hasFromCodes) return userIds;
+    return [...new Set([...userIds, ...fromCodes])];
+  }, [invitationCodeIds.length, resolvedUserIdsFromCodes, userIds]);
+
+  const addUserToFilter = (userId: string) => {
+    setUserIds((prev) =>
+      prev.includes(userId) ? prev : [...prev, userId]
+    );
+  };
+
+  const { data, isLoading, fetchNextPage, hasNextPage, isFetchingNextPage } =
+    useInfiniteQuery({
+      queryKey: [
+        'admin-webtoons',
+        effectiveUserIds,
+        dateRange,
+        searchTerm,
+        tagIds,
+        isPublic,
+        showNsfw
+      ],
+      queryFn: async ({ pageParam }) => {
+        const response = await getAdminWebtoons({
+          cursor: pageParam as string | undefined,
+          userIds: effectiveUserIds.length > 0 ? effectiveUserIds : undefined,
+          startDate: dateRange?.from,
+          endDate: dateRange?.to,
+          searchTerm: searchTerm || undefined,
+          tagIds: tagIds.length > 0 ? tagIds : undefined,
+          isPublic,
+          showNsfw
+        });
+        return response as unknown as {
+          data: AdminWebtoon[];
+          hasMore: boolean;
+          cursor: string | undefined;
+        };
+      },
+      initialPageParam: undefined as string | undefined,
+      getNextPageParam: (lastPage) => lastPage.cursor
+    });
+
+  useEffect(() => {
+    if (inView && hasNextPage) {
+      fetchNextPage();
+    }
+  }, [inView, hasNextPage, fetchNextPage]);
+
+  const webtoons = useMemo(() => {
+    return data?.pages.flatMap((page) => page.data) ?? [];
+  }, [data]);
+
+  const groupedWebtoons = useMemo(() => {
+    if (!webtoons || webtoons.length === 0) return {};
+
+    const groups = webtoons.reduce(
+      (acc, webtoon) => {
+        const dateKey = format(new Date(webtoon.createdAt), 'yyyy-MM-dd');
+        if (!acc[dateKey]) {
+          acc[dateKey] = [];
+        }
+        acc[dateKey].push(webtoon);
+        return acc;
+      },
+      {} as Record<string, AdminWebtoon[]>
+    );
+
+    const sortedDates = Object.keys(groups).sort(
+      (a, b) => new Date(b).getTime() - new Date(a).getTime()
+    );
+
+    const sortedGroups: Record<string, AdminWebtoon[]> = {};
+    for (const date of sortedDates) {
+      sortedGroups[date] = groups[date];
+    }
+    return sortedGroups;
+  }, [webtoons]);
+
+  return (
+    <AdminPageGuard route="webtoons">
+      <div className="container mx-auto py-8">
+        <AdminPageHeader
+          title={t('admin.webtoons.title', { defaultMessage: '條漫管理' })}
+          showBackLink
+          description={t('admin.webtoons.description', {
+            defaultMessage: '管理所有用戶的條漫'
+          })}
+        >
+          <Link href="/admin/webtoons/report">
+            <Button variant="outline" size="sm">
+              <BarChart3 className="h-4 w-4 mr-2" />
+              {t('admin.webtoons.analyze', {
+                defaultMessage: '分析'
+              })}
+            </Button>
+          </Link>
+        </AdminPageHeader>
+
+        <FilterControls
+          userIds={userIds}
+          onUserIdsChange={setUserIds}
+          invitationCodeIds={invitationCodeIds}
+          onInvitationCodeIdsChange={setInvitationCodeIds}
+          showNsfw={showNsfw}
+          setShowNsfw={setShowNsfw}
+          dateRange={dateRange}
+          onDateRangeChange={setDateRange}
+          searchTerm={searchTerm}
+          onSearchTermChange={setSearchTerm}
+          tagIds={tagIds}
+          onTagIdsChange={setTagIds}
+          isPublic={isPublic}
+          onIsPublicChange={setIsPublic}
+        />
+
+        <WebtoonsContent
+          isLoading={isLoading}
+          groupedWebtoons={groupedWebtoons}
+          showNsfw={showNsfw}
+          searchTerm={searchTerm}
+          onAddUserToFilter={addUserToFilter}
+        />
+
+        <div ref={ref} className="h-4" />
+        {isFetchingNextPage && <LoadingMore />}
+      </div>
+    </AdminPageGuard>
+  );
+}
