+'use client';
+
+import { useTranslations } from 'next-intl';
+import { Users, FileImage, TrendingUp, TrendingDown } from 'lucide-react';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange } from '@/utils/stats';
+import type { WebtoonStats } from '@/data/webtoon-stats';
+
+interface UserStatsCardProps {
+  uniqueUsersCount: number;
+  totalCount: number;
+  averagePerUser: number;
+  isLoading?: boolean;
+  previousStats?: WebtoonStats | null;
+  isPreviousLoading?: boolean;
+}
+
+const statItems = [
+  {
+    key: 'uniqueUsers',
+    icon: Users,
+    bgColor: 'bg-blue-500',
+    cardBgColor: 'bg-blue-50 dark:bg-blue-950/20'
+  },
+  {
+    key: 'totalWebtoons',
+    icon: FileImage,
+    bgColor: 'bg-purple-500',
+    cardBgColor: 'bg-purple-50 dark:bg-purple-950/20'
+  },
+  {
+    key: 'averagePerUser',
+    icon: TrendingUp,
+    bgColor: 'bg-emerald-500',
+    cardBgColor: 'bg-emerald-50 dark:bg-emerald-950/20'
+  }
+] as const;
+
+export function UserStatsCard({
+  uniqueUsersCount,
+  totalCount,
+  averagePerUser,
+  isLoading,
+  previousStats,
+  isPreviousLoading
+}: UserStatsCardProps) {
+  const t = useTranslations();
+
+  const previousValues = previousStats
+    ? [
+        previousStats.uniqueUsersCount,
+        previousStats.totalCount,
+        previousStats.averagePerUser
+      ]
+    : [undefined, undefined, undefined];
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
+        {[1, 2, 3].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-4 flex items-center justify-between text-center gap-1">
+              <div className="h-3 w-20 bg-muted rounded mb-2 animate-pulse" />
+              <div className="h-8 w-16 bg-muted rounded animate-pulse" />
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  const values = [uniqueUsersCount, totalCount, averagePerUser];
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
+      {statItems.map((item, index) => {
+        const value = values[index];
+        const previousValue = previousValues[index];
+        const change =
+          previousValue !== undefined
+            ? calculateChange(value, previousValue)
+            : null;
+        const isPositive = change !== null && change > 0;
+        const isNegative = change !== null && change < 0;
+
+        return (
+          <Card
+            key={item.key}
+            className="border shadow-sm hover:shadow-md transition-all"
+          >
+            <CardContent className="p-4">
+              <div className="flex items-center justify-center mb-2">
+                <p className="text-xs text-muted-foreground text-center">
+                  {t(`admin.webtoons.report.${item.key}`)}
+                </p>
+              </div>
+              <p className="flex items-center justify-center gap-1 text-lg md:text-2xl font-bold text-center">
+                {typeof value === 'number' && value % 1 !== 0
+                  ? value.toFixed(2)
+                  : value.toLocaleString()}
+              </p>
+              <div className="flex items-center justify-center gap-1 mt-1">
+                {previousValue !== undefined && !isPreviousLoading && (
+                  <p className="text-xs text-muted-foreground text-center">
+                    {t('admin.webtoons.report.previousPeriod', {
+                      defaultMessage: '前一期'
+                    })}
+                    :{' '}
+                    {typeof previousValue === 'number' &&
+                    previousValue % 1 !== 0
+                      ? previousValue.toFixed(2)
+                      : previousValue.toLocaleString()}
+                  </p>
+                )}
+                {change !== null && !isPreviousLoading && (
+                  <div
+                    className={cn(
+                      'flex items-center gap-1 text-xs font-medium',
+                      isPositive && 'text-emerald-600 dark:text-emerald-400',
+                      isNegative && 'text-red-600 dark:text-red-400',
+                      !isPositive && !isNegative && 'text-muted-foreground'
+                    )}
+                  >
+                    {isPositive ? (
+                      <TrendingUp className="h-3 w-3" />
+                    ) : isNegative ? (
+                      <TrendingDown className="h-3 w-3" />
+                    ) : null}
+                    <span>
+                      {change > 0 ? '+' : ''}
+                      {change.toFixed(1)}%
+                    </span>
+                  </div>
+                )}
+              </div>
+            </CardContent>
+          </Card>
+        );
+      })}
+    </div>
+  );
+}
