+'use client';
+
+import { useTranslations } from 'next-intl';
+import {
+  BarChart,
+  Bar,
+  XAxis,
+  YAxis,
+  CartesianGrid,
+  Tooltip,
+  ResponsiveContainer,
+  LabelList
+} from 'recharts';
+
+interface DailyWebtoonCount {
+  date: string;
+  count: number;
+}
+
+interface WebtoonCountChartProps {
+  data: DailyWebtoonCount[];
+  isLoading?: boolean;
+}
+
+export function WebtoonCountChart({ data, isLoading }: WebtoonCountChartProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return (
+      <div className="h-[300px] flex items-center justify-center">
+        <p className="text-muted-foreground">{t('common.loading')}</p>
+      </div>
+    );
+  }
+
+  if (!data || data.length === 0) {
+    return (
+      <div className="h-[300px] flex items-center justify-center">
+        <p className="text-muted-foreground">
+          {t('admin.webtoons.report.noData', {
+            defaultMessage: '所選期間沒有數據'
+          })}
+        </p>
+      </div>
+    );
+  }
+
+  return (
+    <ResponsiveContainer width="100%" height={300}>
+      <BarChart
+        data={data}
+        margin={{ top: 5, right: 20, left: -25, bottom: 5 }}
+      >
+        <CartesianGrid strokeDasharray="3 3" />
+        <XAxis
+          dataKey="date"
+          tickFormatter={(tick) =>
+            new Date(tick + 'T00:00:00Z').toLocaleDateString('zh-TW', {
+              month: 'short',
+              day: 'numeric',
+              timeZone: 'UTC'
+            })
+          }
+          dy={5}
+        />
+        <YAxis allowDecimals={false} />
+        <Tooltip
+          labelFormatter={(label) =>
+            new Date(label + 'T00:00:00Z').toLocaleDateString('zh-TW', {
+              year: 'numeric',
+              month: 'long',
+              day: 'numeric',
+              timeZone: 'UTC'
+            })
+          }
+          formatter={(value: number) => [
+            value,
+            t('admin.webtoons.report.dailyCount', {
+              defaultMessage: '條漫數量'
+            })
+          ]}
+        />
+        <Bar dataKey="count" fill="#8884d8" name="count">
+          <LabelList
+            dataKey="count"
+            position="top"
+            formatter={(value: number) => (value > 0 ? value : '')}
+            style={{ fontSize: '12px', fill: '#666' }}
+          />
+        </Bar>
+      </BarChart>
+    </ResponsiveContainer>
+  );
+}
