+'use client';
+
+import { useTranslations } from 'next-intl';
+import {
+  Eye,
+  EyeOff,
+  AlertTriangle,
+  Shield,
+  TrendingUp,
+  TrendingDown
+} from 'lucide-react';
+
+import { Card, CardContent } from '@/components/ui/card';
+import { cn } from '@/lib/utils';
+import { calculateChange, calculatePercentage } from '@/utils/stats';
+import type { WebtoonStats } from '@/data/webtoon-stats';
+
+interface WebtoonStatsCardProps {
+  visibilityDistribution: {
+    public: number;
+    private: number;
+  };
+  nsfwDistribution: {
+    nsfw: number;
+    sfw: number;
+  };
+  isLoading?: boolean;
+  previousStats?: WebtoonStats | null;
+  isPreviousLoading?: boolean;
+}
+
+export function WebtoonStatsCard({
+  visibilityDistribution,
+  nsfwDistribution,
+  isLoading,
+  previousStats,
+  isPreviousLoading
+}: WebtoonStatsCardProps) {
+  const t = useTranslations();
+
+  if (isLoading) {
+    return (
+      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
+        {[1, 2].map((i) => (
+          <Card key={i} className="border shadow-sm">
+            <CardContent className="p-4 flex flex-col items-center">
+              <div className="h-3 w-20 bg-muted rounded mb-3 animate-pulse" />
+              <div className="grid grid-cols-2 gap-3 w-full">
+                <div className="flex flex-col items-center">
+                  <div className="h-3 w-12 bg-muted rounded animate-pulse" />
+                  <div className="h-6 w-16 bg-muted rounded mt-1 animate-pulse" />
+                </div>
+                <div className="flex flex-col items-center">
+                  <div className="h-3 w-12 bg-muted rounded animate-pulse" />
+                  <div className="h-6 w-16 bg-muted rounded mt-1 animate-pulse" />
+                </div>
+              </div>
+            </CardContent>
+          </Card>
+        ))}
+      </div>
+    );
+  }
+
+  const totalVisibility =
+    visibilityDistribution.public + visibilityDistribution.private;
+  const publicPercentage = calculatePercentage(
+    visibilityDistribution.public,
+    totalVisibility
+  );
+  const privatePercentage = calculatePercentage(
+    visibilityDistribution.private,
+    totalVisibility
+  );
+
+  const totalNsfw = nsfwDistribution.nsfw + nsfwDistribution.sfw;
+  const nsfwPercentage = calculatePercentage(nsfwDistribution.nsfw, totalNsfw);
+  const sfwPercentage = calculatePercentage(nsfwDistribution.sfw, totalNsfw);
+
+  type StatItem = {
+    label: string;
+    value: number;
+    percentage: number;
+    icon: typeof Eye;
+    previousValue?: number;
+    change: number;
+    color?: string;
+  };
+
+  const statsSections: {
+    title: string;
+    icon: typeof Eye;
+    items: StatItem[];
+  }[] = [
+    {
+      title: t('admin.webtoons.report.visibilityDistribution', {
+        defaultMessage: '公開/私人'
+      }),
+      icon: Eye,
+      items: [
+        {
+          label: t('admin.webtoons.visibility.public', {
+            defaultMessage: '公開'
+          }),
+          value: visibilityDistribution.public,
+          percentage: publicPercentage,
+          icon: Eye,
+          previousValue: previousStats?.visibilityDistribution.public,
+          change: calculateChange(
+            visibilityDistribution.public,
+            previousStats?.visibilityDistribution.public
+          )
+        },
+        {
+          label: t('admin.webtoons.visibility.private', {
+            defaultMessage: '私人'
+          }),
+          value: visibilityDistribution.private,
+          percentage: privatePercentage,
+          icon: EyeOff,
+          previousValue: previousStats?.visibilityDistribution.private,
+          change: calculateChange(
+            visibilityDistribution.private,
+            previousStats?.visibilityDistribution.private
+          )
+        }
+      ]
+    },
+    {
+      title: t('admin.webtoons.report.nsfwDistribution', {
+        defaultMessage: 'NSFW/SFW'
+      }),
+      icon: Shield,
+      items: [
+        {
+          label: t('admin.webtoons.report.nsfw', { defaultMessage: 'NSFW' }),
+          value: nsfwDistribution.nsfw,
+          percentage: nsfwPercentage,
+          icon: AlertTriangle,
+          color: 'text-amber-600 dark:text-amber-400',
+          previousValue: previousStats?.nsfwDistribution.nsfw,
+          change: calculateChange(
+            nsfwDistribution.nsfw,
+            previousStats?.nsfwDistribution.nsfw
+          )
+        },
+        {
+          label: t('admin.webtoons.report.sfw', { defaultMessage: 'SFW' }),
+          value: nsfwDistribution.sfw,
+          percentage: sfwPercentage,
+          icon: Shield,
+          color: 'text-orange-600 dark:text-orange-400',
+          previousValue: previousStats?.nsfwDistribution.sfw,
+          change: calculateChange(
+            nsfwDistribution.sfw,
+            previousStats?.nsfwDistribution.sfw
+          )
+        }
+      ]
+    }
+  ];
+
+  return (
+    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
+      {statsSections.map((section, sectionIndex) => (
+        <Card
+          key={sectionIndex}
+          className="border shadow-sm hover:shadow-md transition-shadow"
+        >
+          <CardContent className="p-3 flex flex-col items-center">
+            <p className="text-xs font-semibold text-muted-foreground mb-3">
+              {section.title}
+            </p>
+            <div className="grid grid-cols-2 gap-3 w-full">
+              {section.items.map((item) => {
+                const ItemIcon = item.icon;
+                const hasChange =
+                  item.previousValue !== undefined && !isPreviousLoading;
+                const isPositive = hasChange && item.change > 0;
+                const isNegative = hasChange && item.change < 0;
+
+                return (
+                  <div
+                    key={item.label}
+                    className="flex flex-col items-center text-center"
+                  >
+                    <div className="flex items-center gap-1 mb-1 bg-slate-100 px-2 py-1 rounded-full">
+                      <ItemIcon
+                        className={cn(
+                          'h-3.5 w-3.5',
+                          item.color ?? 'text-muted-foreground'
+                        )}
+                      />
+                      <p className="text-xs text-muted-foreground">
+                        {item.label}
+                      </p>
+                    </div>
+                    <div className="flex items-center gap-1 justify-center">
+                      <p className="text-xl font-bold">
+                        {item.value.toLocaleString()}
+                      </p>
+                      <p className="text-xs text-muted-foreground">
+                        ({item.percentage}%)
+                      </p>
+                    </div>
+                    {hasChange && (
+                      <div
+                        className={cn(
+                          'flex items-center gap-1 text-xs font-medium',
+                          isPositive &&
+                            'text-emerald-600 dark:text-emerald-400',
+                          isNegative && 'text-red-600 dark:text-red-400',
+                          !isPositive && !isNegative && 'text-muted-foreground'
+                        )}
+                      >
+                        {isPositive ? (
+                          <TrendingUp className="h-3 w-3" />
+                        ) : isNegative ? (
+                          <TrendingDown className="h-3 w-3" />
+                        ) : null}
+                        <span>
+                          {item.change > 0 ? '+' : ''}
+                          {item.change.toFixed(1)}%
+                        </span>
+                      </div>
+                    )}
+                  </div>
+                );
+              })}
+            </div>
+          </CardContent>
+        </Card>
+      ))}
+    </div>
+  );
+}
