+'use client';
+
+import { useState, useMemo } from 'react';
+import { useQuery } from '@tanstack/react-query';
+import { useTranslations } from 'next-intl';
+import type { DateRange } from 'react-day-picker';
+import { BarChart3, TrendingUp } from 'lucide-react';
+
+import { getWebtoonStats } from '@/data/webtoon-stats';
+import { getUserIdByInvitationCodeIdsAction } from '@/actions/admin/invitation-code';
+import { AdminPageGuard } from '@/components/admin/permission-guard';
+import { FilterAndSearch } from '@/components/admin/filter-and-search';
+import { UserSelector } from '@/components/admin/user-selector';
+import { InvitationCodeSelector } from '@/components/admin/invitation-code-selector';
+import { DateRangePicker } from '@/components/ui/date-range-picker';
+import { Button } from '@/components/ui/button';
+import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
+import {
+  type DateRangeType,
+  getDefaultDateRange,
+  getPreviousDateRange,
+  isUsingDefaultRange
+} from '@/utils/stats';
+
+import AdminPageHeader from '../../_components/admin-page-header';
+
+import { WebtoonCountChart } from './_components/webtoon-count-chart';
+import { UserStatsCard } from './_components/user-stats-card';
+import { WebtoonStatsCard } from './_components/webtoon-stats-card';
+import { TagDistributionCard } from './_components/tag-distribution-card';
+
+export default function WebtoonsReportPage() {
+  const t = useTranslations();
+  const [dateRangeType, setDateRangeType] = useState<DateRangeType>('7days');
+  const [selectedDateRange, setSelectedDateRange] = useState<
+    DateRange | undefined
+  >(undefined);
+  const [userIds, setUserIds] = useState<string[]>([]);
+  const [invitationCodeIds, setInvitationCodeIds] = useState<string[]>([]);
+
+  const { data: resolvedUserIdsFromCodes } = useQuery({
+    queryKey: ['admin', 'user-ids-by-invitation-codes', invitationCodeIds],
+    queryFn: () => getUserIdByInvitationCodeIdsAction(invitationCodeIds),
+    enabled: invitationCodeIds.length > 0
+  });
+
+  const effectiveUserIds = useMemo(() => {
+    const fromCodes = resolvedUserIdsFromCodes ?? [];
+    const hasFromCodes = invitationCodeIds.length > 0 && fromCodes.length > 0;
+    if (userIds.length === 0 && !hasFromCodes) return [];
+    if (userIds.length === 0) return fromCodes;
+    if (!hasFromCodes) return userIds;
+    return [...new Set([...userIds, ...fromCodes])];
+  }, [invitationCodeIds.length, resolvedUserIdsFromCodes, userIds]);
+
+  const handleDateRangeTypeChange = (type: DateRangeType) => {
+    setDateRangeType(type);
+    setSelectedDateRange(getDefaultDateRange(type));
+  };
+
+  const dateRange = useMemo(() => {
+    if (selectedDateRange?.from || selectedDateRange?.to) {
+      return selectedDateRange;
+    }
+    return getDefaultDateRange(dateRangeType);
+  }, [selectedDateRange, dateRangeType]);
+
+  const isUsingDefaultRangeValue = useMemo(() => {
+    return isUsingDefaultRange(selectedDateRange, dateRangeType);
+  }, [selectedDateRange, dateRangeType]);
+
+  const previousDateRange = useMemo(() => {
+    if (!isUsingDefaultRangeValue) {
+      return null;
+    }
+    return getPreviousDateRange(dateRangeType);
+  }, [dateRangeType, isUsingDefaultRangeValue]);
+
+  const {
+    data: stats,
+    isLoading,
+    error
+  } = useQuery({
+    queryKey: ['webtoon-stats', dateRange, effectiveUserIds],
+    queryFn: async () => {
+      return await getWebtoonStats({
+        startDate: dateRange?.from,
+        endDate: dateRange?.to,
+        userIds:
+          effectiveUserIds.length > 0 ? effectiveUserIds : undefined
+      });
+    },
+    enabled: !!(dateRange?.from || dateRange?.to)
+  });
+
+  const { data: previousStats, isLoading: isPreviousLoading } = useQuery({
+    queryKey: ['webtoon-stats', previousDateRange, effectiveUserIds],
+    queryFn: async () => {
+      if (!previousDateRange?.from || !previousDateRange?.to) {
+        return null;
+      }
+      return await getWebtoonStats({
+        startDate: previousDateRange.from,
+        endDate: previousDateRange.to,
+        userIds:
+          effectiveUserIds.length > 0 ? effectiveUserIds : undefined
+      });
+    },
+    enabled: !!previousDateRange?.from && !!previousDateRange?.to
+  });
+
+  return (
+    <AdminPageGuard route="webtoons">
+      <div className="container mx-auto py-8">
+        <AdminPageHeader
+          title={t('admin.webtoons.report.title', {
+            defaultMessage: '條漫報表分析'
+          })}
+          showBackLink
+          backLinkHref="/admin/webtoons"
+          description={t('admin.webtoons.report.description', {
+            defaultMessage: '查看條漫相關的統計數據和分析圖表'
+          })}
+        />
+
+        <div className="mb-4">
+          <FilterAndSearch>
+            <div className="flex flex-col sm:flex-row sm:flex-wrap gap-3 w-full">
+              <div className="flex gap-2 flex-wrap shrink-0">
+                {(
+                  ['today', 'yesterday', '7days', '30days'] as DateRangeType[]
+                ).map((type) => (
+                  <Button
+                    key={`webtoons-report-button-${type}`}
+                    variant={dateRangeType === type ? 'default' : 'outline'}
+                    size="sm"
+                    onClick={() => handleDateRangeTypeChange(type)}
+                  >
+                    {t(`admin.webtoons.report.${type}`, {
+                      defaultMessage:
+                        type === 'today'
+                          ? '今日'
+                          : type === 'yesterday'
+                          ? '昨日'
+                          : type === '7days'
+                          ? '7天'
+                          : '30天'
+                    })}
+                  </Button>
+                ))}
+              </div>
+              <div className="w-full sm:w-auto shrink-0">
+                <DateRangePicker
+                  className="w-full flex-col sm:flex-row"
+                  date={selectedDateRange || getDefaultDateRange(dateRangeType)}
+                  onDateChange={setSelectedDateRange}
+                  placeholder={t('common.dateRangePicker.selectDateRange', {
+                    defaultMessage: '選擇日期範圍'
+                  })}
+                />
+              </div>
+              <div className="w-full sm:w-auto sm:min-w-[200px] sm:max-w-[280px] shrink-0">
+                <UserSelector
+                  value={userIds}
+                  onValueChange={(value) => {
+                    setUserIds(Array.isArray(value) ? value : []);
+                  }}
+                  className="w-full"
+                  multiple
+                  maxDisplayCount={2}
+                />
+              </div>
+              <div className="w-full sm:w-auto sm:min-w-[200px] sm:max-w-[280px] shrink-0">
+                <InvitationCodeSelector
+                  value={invitationCodeIds}
+                  onValueChange={setInvitationCodeIds}
+                  className="w-full"
+                  maxDisplayCount={2}
+                />
+              </div>
+            </div>
+          </FilterAndSearch>
+        </div>
+
+        {error && (
+          <Card className="mb-6 border-destructive">
+            <CardContent className="pt-6">
+              <p className="text-destructive">
+                {t('admin.webtoons.report.error', {
+                  defaultMessage: '載入數據時發生錯誤'
+                })}
+              </p>
+            </CardContent>
+          </Card>
+        )}
+
+        {stats && (
+          <div className="space-y-6">
+            <div>
+              <h3 className="text-sm font-semibold text-muted-foreground mb-3">
+                {t('admin.webtoons.report.userStats', {
+                  defaultMessage: '使用者統計'
+                })}
+              </h3>
+              <UserStatsCard
+                uniqueUsersCount={stats.uniqueUsersCount}
+                totalCount={stats.totalCount}
+                averagePerUser={stats.averagePerUser}
+                isLoading={isLoading}
+                previousStats={previousStats}
+                isPreviousLoading={isPreviousLoading}
+              />
+            </div>
+
+            <div>
+              <h3 className="text-sm font-semibold text-muted-foreground mb-3">
+                {t('admin.webtoons.report.webtoonStats', {
+                  defaultMessage: '條漫統計'
+                })}
+              </h3>
+              <WebtoonStatsCard
+                visibilityDistribution={stats.visibilityDistribution}
+                nsfwDistribution={stats.nsfwDistribution}
+                isLoading={isLoading}
+                previousStats={previousStats}
+                isPreviousLoading={isPreviousLoading}
+              />
+            </div>
+
+            <div>
+              <h3 className="text-sm font-semibold text-muted-foreground mb-3">
+                {t('admin.webtoons.report.tagDistribution', {
+                  defaultMessage: '標籤分佈'
+                })}
+              </h3>
+              <TagDistributionCard
+                tagDistribution={stats.tagDistribution}
+                isLoading={isLoading}
+                previousStats={previousStats}
