+import type { AdminWebtoon } from '@/data/admin/webtoon';
+import UserBadge from '@/components/user-badge';
+import VisibilityButton from '@/components/button/visibility-button';
+import { updateWebtoonVisibilityByAdmin } from '@/actions/admin/webtoon';
+import {
+  ActionDropdownMenu,
+  type ActionItem
+} from '@/components/action-dropdown-menu';
+
+import { DeleteWebtoonDialog } from './delete-webtoon-dialog';
+
+/** API 回傳的 slice 結構（與 fetchWebtoonSlices 一致） */
+interface WebtoonSliceItem {
+  id: string;
+  order: number;
+  image: { url: string; rawUrl?: string } | null;
+  webtoonId: string;
+}
+
+interface WebtoonCardProps {
