+                alt={webtoon.name}
+                fill
+                className={`object-cover ${
+                  webtoon.isNsfw && !showNsfw ? 'filter blur-md' : ''
+                }`}
+              />
+            ) : (
+              <div className="w-full h-full bg-gray-200 flex items-center justify-center">
+                <BookOpen className="w-12 h-12 text-gray-400" />
