+'use client';
+
+import { useTranslations } from 'next-intl';
+
+import { MultiCombobox, ComboboxOption } from '@/components/ui/comboBox';
+
+export type ArtworkTypeValue = 'image' | 'video' | 'all';
+
+export interface ArtworkTypeFilterProps {
+  value: ArtworkTypeValue;
+  onValueChange: (value: ArtworkTypeValue) => void;
+  className?: string;
+}
+
+const IMAGE_VALUE = 'image';
+const VIDEO_VALUE = 'video';
+
+/**
+ * 將 ArtworkTypeValue 轉為 MultiCombobox 的 string[]
+ * all（全部）→ []；image → ['image']；video → ['video']
+ */
+function toMultiValue(value: ArtworkTypeValue): string[] {
+  if (value === 'all') return [];
+  return [value];
+}
+
+/**
+ * 將 MultiCombobox 的 string[] 轉為 ArtworkTypeValue
+ * [] 或 ['image','video'] → all；僅 image → image；僅 video → video
+ */
+function fromMultiValue(selected: string[]): ArtworkTypeValue {
+  if (selected.length === 0 || selected.length === 2) return 'all';
+  return selected[0] === IMAGE_VALUE ? 'image' : 'video';
+}
+
+/**
+ * 作品類型篩選（多選）：使用 MultiCombobox，圖片 / 影片可複選
+ * 兩者皆選或皆不選 = 全部類型；僅選圖片
